	defer rows.Close()
	items := []ListCreatorArticlesRow{}
	for rows.Next() {
		var i ListCreatorArticlesRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Slug,
			&i.Content,
			&i.ImageUrl,
			&i.Published,
			&i.IsPremium,
			&i.Visibility,
			&i.ReadingTime,
			&i.Status,
			&i.TierId,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CategoryID,
			&i.CategoryName,
			&i.CategorySlug,
			&i.CategoryDescription,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
